import torch, math
from torch import nn
class Head(nn.Module):
    def __init__(self, width):
        super().__init__()
        self.q, self.k, self.v = [nn.Linear(width, width, bias=False) for _ in range(3)]
        with torch.no_grad():
            for layer in (self.q, self.k, self.v):
                layer.weight.copy_(torch.eye(width))
    def forward(self, x):
        scores = self.q(x) @ self.k(x).T / math.sqrt(x.shape[-1])
        return scores.softmax(-1) @ self.v(x)
x = torch.tensor([[1., 0.], [0., 1.], [1., 0.]])
head = Head(2)
out = head(x)
print(tuple(out.shape), [round(float(v.detach()), 3) for v in out[0]])
